import sqlite3

def add_user(db, name, email):
    try:
        db.execute("insert into users (name, email) values (?, ?)", (name, email))
        db.commit()
        print("ok")
        return 1
    except:
        return 0

def recent_users(db):
    try:
        return db.execute("select * from users order by created desc limit 50").fetchall()
    except:
        return []

def search_users(db, q):
    try:
        # search the users
        return db.execute("select * from users where name like ? limit 50", ("%" + q + "%",)).fetchall()
    except:
        return []

def find_users_by_domain(db, domain):
    try:
        # escape LIKE wildcards so the domain is matched literally
        d = domain.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        return db.execute("select * from users where email like ? escape '\\' limit 50", ("%@" + d,)).fetchall()
    except:
        return []
```

Notes:
- It follows the existing pattern: parameterized query, `limit 50`, and a bare `except` that returns `[]`.
- The `%@<domain>` pattern anchors the match to the end of the email, so `example.com` won't match `user@notexample.com` or `user@example.com.evil.org`.
- `%` and `_` in the input are escaped so they match literally rather than acting as wildcards.
- SQLite's `LIKE` is case-insensitive for ASCII, so `Example.COM` matches `example.com`.
- Like the other queries, it has no `order by`, so which 50 rows you get isn't deterministic. If you want stable paging, add `order by created desc` as `recent_users` does.
